function preimageSizeFZF(k) {
  function trailingZeros(x) {
    let count = 0;
    while (x > 0) {
      x = Math.floor(x / 5);
      count += x;
    }
    return count;
  }

  let left = 0;
  let right = 5 * (k + 1);
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (trailingZeros(mid) < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return trailingZeros(left) === k ? 5 : 0;
}

