function preimageSizeFZF(k) {
  // Walk x upwards, adding the factors of 5 that x contributes to x!.
  let zeros = 0;
  let found = 0;
  for (let x = 0; zeros <= k; x++) {
    if (x > 0) {
      let v = x;
      while (v % 5 === 0) { zeros++; v /= 5; }
    }
    if (zeros === k) found++;
  }
  return found;
}

